  if (selection) { selection.removeAllRanges(); ranges.forEach(range => selection.addRange(range)); }
  active?.focus?.({ preventScroll: true });
  if (!ok) throw new Error("Copy failed");
}

/** Shared clipboard state for actions that render their own button or menu. */
export function useCopyFeedback(duration = 1900) {
  const [state, setState] = useState<CopyFeedbackState>("idle");
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const timeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  const reset = useCallback(() => {
    if (timeout.current) clearTimeout(timeout.current);
    timeout.current = null;
    setState("idle");
    setActiveKey(null);
  }, []);

  useEffect(() => () => {
    if (timeout.current) clearTimeout(timeout.current);
  }, []);

  const copy = useCallback(async (value: string, key = "default") => {
    if (timeout.current) clearTimeout(timeout.current);
    setActiveKey(key);
    try {
      await writeClipboard(value);
      setState("copied");
      timeout.current = setTimeout(reset, duration);
      return true;
    } catch {
      setState("error");
      timeout.current = setTimeout(reset, duration);
      return false;
    }
  }, [duration, reset]);

  return { state, activeKey, copy, reset };
}

"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import type { CSSProperties, ReactNode } from "react";
import { motion, useAnimationFrame, useInView, useMotionValue, useReducedMotion, useSpring, useTransform } from "motion/react";
import styles from "./marquee.module.css";

/**
 * An endless scroller for logos, quotes or tickers. The content repeats as often as needed to fill the track and loops without a seam.
 * Hovering or focusing it eases the motion to a stop instead of freezing it, and it rests while off screen.
 * With reduced motion it does not move on its own: the track becomes an ordinary scroll area.
 */
export interface MarqueeProps {
  /** The items to scroll. They are laid out in a row, or in a column for the vertical directions. */
  children: ReactNode;
  /** Where the content travels. `left` and `right` scroll a row; `up` and `down` scroll a column and need a height on the marquee. */
  direction?: "left" | "right" | "up" | "down";
  /** Travel speed in px per second. */
  speed?: number;
  /** Space between items, and between one repetition and the next, in px or any CSS length. */
  gap?: number | string;
  /** Slows to a stop while the pointer is over the marquee or focus is inside it. */
  pauseOnHover?: boolean;
  /** Stops the motion, for a pause button. People must be able to stop content that moves for more than a few seconds. */
  paused?: boolean;
  /** Fades the two edges the content enters and leaves through. Pass a CSS length to set how wide the fade is. */
  fade?: boolean | string;
  /** Accessible name for the group, for example "Customers". */
  label?: string;
  /** Extra class names for the root element. */
  className?: string;
  /** Inline styles for the root element, for sizes and CSS variables. */
  style?: CSSProperties;
}

const MAX_COPIES = 24;
// Useless on the server, harmless in the browser: measure before paint so the first frame already has enough copies.
const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export function Marquee({ children, direction = "left", speed = 48, gap = 24, pauseOnHover = true, paused = false, fade = true, label, className, style }: MarqueeProps) {
  const reduce = !!useReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const groupRef = useRef<HTMLDivElement>(null);
  const inView = useInView(rootRef, { margin: "80px" });
  const vertical = direction === "up" || direction === "down";
  const reverse = direction === "right" || direction === "down";

  /** Length of one repetition including its trailing gap, and how many repetitions cover the track plus one spare. */
  const [period, setPeriod] = useState(0);
  const [copies, setCopies] = useState(2);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);

  useIsomorphicLayoutEffect(() => {
    const root = rootRef.current, group = groupRef.current;
    if (!root || !group) return;
    const measure = () => {
      const size = vertical ? group.offsetHeight : group.offsetWidth;
      const track = vertical ? root.clientHeight : root.clientWidth;
      const style = getComputedStyle(group);
      const space = parseFloat(vertical ? style.rowGap : style.columnGap) || 0;
      const next = size + space;
      setPeriod(next);
      // The last repetition has no trailing gap, so the track must cover one gap more than its own length.
      setCopies(next > 0 ? Math.min(Math.ceil((track + space) / next) + 1, MAX_COPIES) : 2);
    };
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    observer.observe(group);
    return () => observer.disconnect();
  }, [vertical, gap]);

  const running = !reduce && !paused && inView && !(pauseOnHover && (hovered || focused));
  // The pace eases between 0 and 1, so a pause is a gentle stop and a resume a gentle start.
  const target = useMotionValue(running ? 1 : 0);
  const pace = useSpring(target, { stiffness: 120, damping: 24, mass: 0.6 });
  useEffect(() => { target.set(running ? 1 : 0); }, [running, target]);

  const offset = useMotionValue(0);
  useAnimationFrame((_, delta) => {
    if (reduce || period <= 0) return;
    const rate = pace.get();
    if (rate < 0.001) return;
    // A long frame (a background tab waking up) must not teleport the content.
    const step = speed * rate * Math.min(delta, 64) / 1000;
    offset.set((offset.get() + step) % period);
  });
  // Reverse starts one repetition back and walks forward, so the track is covered in both directions.
  const shift = useTransform(offset, value => reverse ? value - period : -value);

  const fadeSize = fade === true ? "12%" : fade || undefined;
  const vars = { "--marquee-gap": typeof gap === "number" ? `${gap}px` : gap, ...(fadeSize ? { "--marquee-fade": fadeSize } : null) } as CSSProperties;

  return (
    <div
      ref={rootRef}
      role={label ? "group" : undefined}
      aria-label={label}
      className={[styles.marquee, className].filter(Boolean).join(" ")}
      style={{ ...vars, ...style }}
      data-axis={vertical ? "y" : "x"}
      data-fade={fadeSize ? "" : undefined}
      data-static={reduce ? "" : undefined}
      tabIndex={reduce ? 0 : undefined}
      onPointerEnter={event => { if (event.pointerType === "mouse") setHovered(true); }}
      onPointerLeave={() => setHovered(false)}
      onFocus={() => setFocused(true)}
      onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}
    >
      <motion.div className={styles.track} style={reduce ? undefined : vertical ? { y: shift } : { x: shift }}>
        <div ref={groupRef} className={styles.group}>{children}</div>
        {/* Repetitions are decoration: hidden from assistive tech and out of the tab order, so each item is announced and focused once. */}
        {reduce ? null : Array.from({ length: Math.max(copies - 1, 1) }, (_, index) => <div key={index} className={styles.group} aria-hidden="true" inert>{children}</div>)}
      </motion.div>
    </div>
  );
}

export default Marquee;

.marquee { position: relative; display: flex; max-width: 100%; overflow: hidden; }
.marquee[data-axis="y"] { height: 100%; flex-direction: column; }
/* The edge fade is a mask, not a painted gradient: content dissolves into whatever is behind the marquee.
   Only the alpha of the mask counts, so any opaque token works as the solid stop. */
.marquee[data-fade][data-axis="x"] { mask-image: linear-gradient(to right, transparent, var(--foreground) var(--marquee-fade), var(--foreground) calc(100% - var(--marquee-fade)), transparent); }
.marquee[data-fade][data-axis="y"] { mask-image: linear-gradient(to bottom, transparent, var(--foreground) var(--marquee-fade), var(--foreground) calc(100% - var(--marquee-fade)), transparent); }

.track { display: flex; flex: none; gap: var(--marquee-gap); will-change: transform; }
.group { display: flex; flex: none; align-items: center; gap: var(--marquee-gap); }
.marquee[data-axis="x"] .track { min-width: max-content; }
.marquee[data-axis="y"] .track, .marquee[data-axis="y"] .group { flex-direction: column; }
.marquee[data-axis="y"] .group { align-items: stretch; }

/* Reduced motion: nothing moves by itself, and the content is reached by scrolling instead. */
.marquee[data-static] { scrollbar-width: thin; }
.marquee[data-static][data-axis="x"] { overflow-x: auto; }
.marquee[data-static][data-axis="y"] { overflow-y: auto; }
.marquee[data-static] .track { will-change: auto; }

"use client";

import { useEffect, useId, useLayoutEffect, useRef, type KeyboardEvent, type ReactNode } from "react";
import { LayoutGroup, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "@/lib/motion-tokens";
import styles from "./segmented-control.module.css";

export interface Segment { value: string; label: string; /** Optional content after the label, such as a badge. */ accessory?: ReactNode; }
export interface SegmentedControlProps {
  options: Segment[];
  value: string;
  onValueChange: (value: string) => void;
  label?: string;
  /** Called when the pointer or focus reaches an option, before it is chosen. Use it to start loading what that option shows. */
  onOptionIntent?: (value: string) => void;
  className?: string;
}

export default function SegmentedControl({ options, value, onValueChange, label, onOptionIntent, className }: SegmentedControlProps) {
  const id = useId();
  const reduced = useReducedMotion();
  const track = useRef<HTMLDivElement>(null);

  // When the options are wider than the container, the track scrolls inside itself. Edges fade only on the side with more to see.
  useLayoutEffect(() => {
    const node = track.current;
    if (!node) return;
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft;
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1);
      node.toggleAttribute("data-fade-end", rest > 1);
    };
    edges();
    node.addEventListener("scroll", edges, { passive: true });
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges);
    observer?.observe(node);
    return () => { node.removeEventListener("scroll", edges); observer?.disconnect(); };
  }, [options.length]);

  // The selected option is always scrolled fully into view, with a little room so it clears the fade.
  const first = useRef(true);
  useEffect(() => {
    const node = track.current;
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]');
    if (!node || !button || node.scrollWidth <= node.clientWidth) { first.current = false; return; }
    const room = 20, start = button.offsetLeft - room, end = button.offsetLeft + button.offsetWidth + room - node.clientWidth;
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft;
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" });
    first.current = false;
  }, [value, reduced]);

  // Arrow keys, Home and End move the selection like a tab list; only the selected option is a tab stop.
  const selectedIndex = Math.max(0, options.findIndex(option => option.value === value));
  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const last = options.length - 1;
    const target = event.key === "ArrowRight" || event.key === "ArrowDown" ? (selectedIndex === last ? 0 : selectedIndex + 1)
      : event.key === "ArrowLeft" || event.key === "ArrowUp" ? (selectedIndex === 0 ? last : selectedIndex - 1)
        : event.key === "Home" ? 0 : event.key === "End" ? last : -1;
    if (target < 0 || !options[target]) return;
    event.preventDefault();
    onValueChange(options[target].value);
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true });
  };

  return <div className={`${styles.root} ${className ?? ""}`} role="group" aria-label={label}>
    <LayoutGroup id={id}><motion.div ref={track} layoutScroll className={styles.track}>
      {options.map((option, index) => <button key={option.value} id={`${id}-${option.value}`} className={styles.button} type="button" data-value={option.value} aria-pressed={value === option.value} tabIndex={index === selectedIndex ? 0 : -1} onClick={() => onValueChange(option.value)} onKeyDown={onKeyDown} onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined} onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}>
        {value === option.value && <motion.span className={styles.selection} layoutId="selection" layoutDependency={value} transition={reduced ? { duration: 0 } : motionTokens.spring.morph} aria-hidden="true" />}
        <span className={styles.label}>{option.label}{option.accessory}</span>
      </button>)}
    </motion.div></LayoutGroup>
  </div>;
}

/* The frame can shrink below its content inside flex and grid parents; the track then scrolls inside it. */
.root { display: inline-flex; min-width: 0; max-width: 100%; flex-shrink: 1; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-muted); }
/* The track owns the stacking context so the gliding highlight passes under every label, not over earlier ones. */
.track { --fade-start: 0px; --fade-end: 0px; isolation: isolate; display: flex; min-width: 0; gap: 2px; overflow-x: auto; overscroll-behavior-x: contain; padding: 3px; border-radius: inherit; scrollbar-width: none; -webkit-mask-image: linear-gradient(to right, transparent, #000 var(--fade-start), #000 calc(100% - var(--fade-end)), transparent); mask-image: linear-gradient(to right, transparent, #000 var(--fade-start), #000 calc(100% - var(--fade-end)), transparent); }
.track::-webkit-scrollbar { display: none; }
.track[data-fade-start] { --fade-start: 20px; }
.track[data-fade-end] { --fade-end: 20px; }
/* Items never scale or change weight; only the highlight travels and the label color follows it. */
.button { position: relative; flex: 0 0 auto; min-height: var(--control-height-sm); border: 0; border-radius: calc(var(--radius-control) - 4px); padding: 0 12px; background: transparent; color: var(--text-muted); font: inherit; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .button:hover { color: var(--foreground); } }
.button:active, .button[aria-pressed="true"] { color: var(--foreground); }
.selection { position: absolute; z-index: -1; inset: 0; border: 1px solid var(--border); border-radius: inherit; background: var(--surface); box-shadow: var(--shadow-resting); }
.label { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: 6px; }
@media (max-width: 380px) { .button { padding: 0 10px; } }
@media (prefers-reduced-motion: reduce) { .button { transition: none; } }
